Based on the commit message, the root cause and the patch provided below, you need to:

1. explain how the bug occurs, including all code statements that are most likely to lead to the bug and why. 
2. explain how the bug is fixed, including code statements fixing the bug and why. 

You must include one or more code statements in point 1 and 2.
Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
ext4: fix use-after-free in update_super_work when racing
 with umount

Commit b98535d09179 ("ext4: fix bug_on in start_this_handle during umount
filesystem") moved ext4_unregister_sysfs() before flushing s_sb_upd_work
to prevent new error work from being queued via /proc/fs/ext4/xx/mb_groups
reads during unmount. However, this introduced a use-after-free because
update_super_work calls ext4_notify_error_sysfs() -> sysfs_notify() which
accesses the kobject's kernfs_node after it has been freed by kobject_del()
in ext4_unregister_sysfs():

  update_super_work                ext4_put_super
  -----------------                --------------
                                   ext4_unregister_sysfs(sb)
                                     kobject_del(&sbi->s_kobj)
                                       __kobject_del()
                                         sysfs_remove_dir()
                                           kobj->sd = NULL
                                         sysfs_put(sd)
                                           kernfs_put()  // RCU free
  ext4_notify_error_sysfs(sbi)
    sysfs_notify(&sbi->s_kobj)
      kn = kobj->sd              // stale pointer
      kernfs_get(kn)             // UAF on freed kernfs_node
                                   ext4_journal_destroy()
                                     flush_work(&sbi->s_sb_upd_work)

Instead of reordering the teardown sequence, fix this by making
ext4_notify_error_sysfs() detect that sysfs has already been torn down
by checking s_kobj.state_in_sysfs, and skipping the sysfs_notify() call
in that case. A dedicated mutex (s_error_notify_mutex) serializes
ext4_notify_error_sysfs() against kobject_del() in ext4_unregister_sysfs()
to prevent TOCTOU races where the kobject could be deleted between the
state_in_sysfs check and the sysfs_notify() call.

Fixes: b98535d09179 ("ext4: fix bug_on in start_this_handle during umount filesystem")
Cc: Jiayuan Chen <jiayuan.chen@linux.dev>
Suggested-by: Jan Kara <jack@suse.cz>
Signed-off-by: Jiayuan Chen <jiayuan.chen@shopee.com>
Reviewed-by: Ritesh Harjani (IBM) <ritesh.list@gmail.com>
Reviewed-by: Jan Kara <jack@suse.cz>
Link: https://patch.msgid.link/20260319120336.157873-1-jiayuan.chen@linux.dev
Signed-off-by: Theodore Ts'o <tytso@mit.edu>
Cc: stable@kernel.org

Here is the root cause:
the work item update_super_work can still be executing after kobject_del, and when it calls ext4_notify_error_sysfs() -> sysfs_notify(), it accesses freed memory, leading to use-after-free.

Here is the patch:

 static int __ext4_fill_super(struct fs_context *fc, struct super_block *sb)
 {
 	struct ext4_super_block *es = NULL;
 	struct ext4_sb_info *sbi = EXT4_SB(sb);
 	ext4_fsblk_t logical_sb_block;
 	struct inode *root;
 	int needs_recovery;
 	int err;
 	ext4_group_t first_not_zeroed;
 	struct ext4_fs_context *ctx = fc->fs_private;
 	int silent = fc->sb_flags & SB_SILENT;

 	/* Set defaults for the variables that will be set during parsing */
 	if (!(ctx->spec & EXT4_SPEC_JOURNAL_IOPRIO))
 		ctx->journal_ioprio = EXT4_DEF_JOURNAL_IOPRIO;

 	sbi->s_inode_readahead_blks = EXT4_DEF_INODE_READAHEAD_BLKS;
 	sbi->s_sectors_written_start =
 		part_stat_read(sb->s_bdev, sectors[STAT_WRITE]);

 	err = ext4_load_super(sb, &logical_sb_block, silent);
 	if (err)
 		goto out_fail;

 	es = sbi->s_es;
 	sbi->s_kbytes_written = le64_to_cpu(es->s_kbytes_written);

 	err = ext4_init_metadata_csum(sb, es);
 	if (err)
 		goto failed_mount;

 	ext4_set_def_opts(sb, es);

 	sbi->s_resuid = make_kuid(&init_user_ns, ext4_get_resuid(es));
 	sbi->s_resgid = make_kgid(&init_user_ns, ext4_get_resuid(es));
 	sbi->s_commit_interval = JBD2_DEFAULT_MAX_COMMIT_AGE * HZ;
 	sbi->s_min_batch_time = EXT4_DEF_MIN_BATCH_TIME;
 	sbi->s_max_batch_time = EXT4_DEF_MAX_BATCH_TIME;
 	sbi->s_sb_update_kb = EXT4_DEF_SB_UPDATE_INTERVAL_KB;
 	sbi->s_sb_update_sec = EXT4_DEF_SB_UPDATE_INTERVAL_SEC;

 	/*
 	 * set default s_li_wait_mult for lazyinit, for the case there is
 	 * no mount option specified.
 	 */
 	sbi->s_li_wait_mult = EXT4_DEF_LI_WAIT_MULT;

 	err = ext4_inode_info_init(sb, es);
 	if (err)
 		goto failed_mount;

 	err = parse_apply_sb_mount_options(sb, ctx);
 	if (err < 0)
 		goto failed_mount;

 	sbi->s_def_mount_opt = sbi->s_mount_opt;
 	sbi->s_def_mount_opt2 = sbi->s_mount_opt2;

 	err = ext4_check_opt_consistency(fc, sb);
 	if (err < 0)
 		goto failed_mount;

 	ext4_apply_options(fc, sb);

 	err = ext4_check_large_folio(sb);
 	if (err < 0)
 		goto failed_mount;

 	err = ext4_encoding_init(sb, es);
 	if (err)
 		goto failed_mount;

 	err = ext4_check_journal_data_mode(sb);
 	if (err)
 		goto failed_mount;

 	sb->s_flags = (sb->s_flags & ~SB_POSIXACL) |
 		(test_opt(sb, POSIX_ACL) ? SB_POSIXACL : 0);

 	/* HSM events are allowed by default. */
 	sb->s_iflags |= SB_I_ALLOW_HSM;

 	err = ext4_check_feature_compatibility(sb, es, silent);
 	if (err)
 		goto failed_mount;

 	err = ext4_block_group_meta_init(sb, silent);
 	if (err)
 		goto failed_mount;

 	err = ext4_hash_info_init(sb);
 	if (err)
 		goto failed_mount;

 	err = ext4_handle_clustersize(sb);
 	if (err)
 		goto failed_mount;

 	err = ext4_check_geometry(sb, es);
 	if (err)
 		goto failed_mount;

 	timer_setup(&sbi->s_err_report, print_daily_error_info, 0);
 	spin_lock_init(&sbi->s_error_lock);
+	mutex_init(&sbi->s_error_notify_mutex);
 	INIT_WORK(&sbi->s_sb_upd_work, update_super_work);

 	err = ext4_group_desc_init(sb, es, logical_sb_block, &first_not_zeroed);
 	if (err)
 		goto failed_mount3;

 	err = ext4_es_register_shrinker(sbi);
 	if (err)
 		goto failed_mount3;

 	sbi->s_stripe = ext4_get_stripe_size(sbi);
 	if (ext4_is_stripe_incompatible(sb, sbi->s_stripe)) {
 		ext4_msg(sb, KERN_WARNING,
 			 "stripe (%lu) is not aligned with cluster size (%u), "
 			 "stripe is disabled",
 			 sbi->s_stripe, sbi->s_cluster_ratio);
 		sbi->s_stripe = 0;
 	}
 	sbi->s_extent_max_zeroout_kb = 32;

 	/*
 	 * set up enough so that it can read an inode
 	 */
 	sb->s_op = &ext4_sops;
 	sb->s_export_op = &ext4_export_ops;
 	sb->s_xattr = ext4_xattr_handlers;
 #ifdef CONFIG_FS_ENCRYPTION
 	sb->s_cop = &ext4_cryptops;
 #endif
 #ifdef CONFIG_FS_VERITY
 	sb->s_vop = &ext4_verityops;
 #endif
 #ifdef CONFIG_QUOTA
 	sb->dq_op = &ext4_quota_operations;
 	if (ext4_has_feature_quota(sb))
 		sb->s_qcop = &dquot_quotactl_sysfile_ops;
 	else
 		sb->s_qcop = &ext4_qctl_operations;
 	sb->s_quota_types = QTYPE_MASK_USR | QTYPE_MASK_GRP | QTYPE_MASK_PRJ;
 #endif
 	super_set_uuid(sb, es->s_uuid, sizeof(es->s_uuid));
 	super_set_sysfs_name_bdev(sb);

 	INIT_LIST_HEAD(&sbi->s_orphan); /* unlinked but open files */
 	mutex_init(&sbi->s_orphan_lock);

 	spin_lock_init(&sbi->s_bdev_wb_lock);

 	ext4_atomic_write_init(sb);
 	ext4_fast_commit_init(sb);

 	sb->s_root = NULL;

 	needs_recovery = (es->s_last_orphan != 0 ||
 			  ext4_has_feature_orphan_present(sb) ||
 			  ext4_has_feature_journal_needs_recovery(sb));

 	if (ext4_has_feature_mmp(sb) && !sb_rdonly(sb)) {
 		err = ext4_multi_mount_protect(sb, le64_to_cpu(es->s_mmp_block));
 		if (err)
 			goto failed_mount3a;
 	}

 	err = -EINVAL;
 	/*
 	 * The first inode we look at is the journal inode.  Don't try
 	 * root first: it may be modified in the journal!
 	 */
 	if (!test_opt(sb, NOLOAD) && ext4_has_feature_journal(sb)) {
 		err = ext4_load_and_init_journal(sb, es, ctx);
 		if (err)
 			goto failed_mount3a;
 		if (bdev_read_only(sb->s_bdev))
 		    needs_recovery = 0;
 	} else if (test_opt(sb, NOLOAD) && !sb_rdonly(sb) &&
 		   ext4_has_feature_journal_needs_recovery(sb)) {
 		ext4_msg(sb, KERN_ERR, "required journal recovery "
 		       "suppressed and not mounted read-only");
 		goto failed_mount3a;
 	} else {
 		const char *journal_option;

 		/* Nojournal mode, all journal mount options are illegal */
 		journal_option = ext4_has_journal_option(sb);
 		if (journal_option != NULL) {
 			ext4_msg(sb, KERN_ERR,
 				 "can't mount with %s, fs mounted w/o journal",
 				 journal_option);
 			goto failed_mount3a;
 		}

 		sbi->s_def_mount_opt &= ~EXT4_MOUNT_JOURNAL_CHECKSUM;
 		clear_opt(sb, JOURNAL_CHECKSUM);
 		clear_opt(sb, DATA_FLAGS);
 		clear_opt2(sb, JOURNAL_FAST_COMMIT);
 		sbi->s_journal = NULL;
 		needs_recovery = 0;
 	}

 	if (!test_opt(sb, NO_MBCACHE)) {
 		sbi->s_ea_block_cache = ext4_xattr_create_cache();
 		if (!sbi->s_ea_block_cache) {
 			ext4_msg(sb, KERN_ERR,
 				 "Failed to create ea_block_cache");
 			err = -EINVAL;
 			goto failed_mount_wq;
 		}

 		if (ext4_has_feature_ea_inode(sb)) {
 			sbi->s_ea_inode_cache = ext4_xattr_create_cache();
 			if (!sbi->s_ea_inode_cache) {
 				ext4_msg(sb, KERN_ERR,
 					 "Failed to create ea_inode_cache");
 				err = -EINVAL;
 				goto failed_mount_wq;
 			}
 		}
 	}

 	/*
 	 * Get the # of file system overhead blocks from the
 	 * superblock if present.
 	 */
 	sbi->s_overhead = le32_to_cpu(es->s_overhead_clusters);
 	/* ignore the precalculated value if it is ridiculous */
 	if (sbi->s_overhead > ext4_blocks_count(es))
 		sbi->s_overhead = 0;
 	/*
 	 * If the bigalloc feature is not enabled recalculating the
 	 * overhead doesn't take long, so we might as well just redo
 	 * it to make sure we are using the correct value.
 	 */
 	if (!ext4_has_feature_bigalloc(sb))
 		sbi->s_overhead = 0;
 	if (sbi->s_overhead == 0) {
 		err = ext4_calculate_overhead(sb);
 		if (err)
 			goto failed_mount_wq;
 	}

 	/*
 	 * The maximum number of concurrent works can be high and
 	 * concurrency isn't really necessary.  Limit it to 1.
 	 */
 	EXT4_SB(sb)->rsv_conversion_wq =
 		alloc_workqueue("ext4-rsv-conversion", WQ_MEM_RECLAIM | WQ_UNBOUND, 1);
 	if (!EXT4_SB(sb)->rsv_conversion_wq) {
 		printk(KERN_ERR "EXT4-fs: failed to create workqueue\n");
 		err = -ENOMEM;
 		goto failed_mount4;
 	}

 	/*
 	 * The jbd2_journal_load will have done any necessary log recovery,
 	 * so we can safely mount the rest of the filesystem now.
 	 */

 	root = ext4_iget(sb, EXT4_ROOT_INO, EXT4_IGET_SPECIAL);
 	if (IS_ERR(root)) {
 		ext4_msg(sb, KERN_ERR, "get root inode failed");
 		err = PTR_ERR(root);
 		root = NULL;
 		goto failed_mount4;
 	}
 	if (!S_ISDIR(root->i_mode) || !root->i_blocks || !root->i_size) {
 		ext4_msg(sb, KERN_ERR, "corrupt root inode, run e2fsck");
 		iput(root);
 		err = -EFSCORRUPTED;
 		goto failed_mount4;
 	}

 	generic_set_sb_d_ops(sb);
 	sb->s_root = d_make_root(root);
 	if (!sb->s_root) {
 		ext4_msg(sb, KERN_ERR, "get root dentry failed");
 		err = -ENOMEM;
 		goto failed_mount4;
 	}

 	err = ext4_setup_super(sb, es, sb_rdonly(sb));
 	if (err == -EROFS) {
 		sb->s_flags |= SB_RDONLY;
 	} else if (err)
 		goto failed_mount4a;

 	ext4_set_resv_clusters(sb);

 	if (test_opt(sb, BLOCK_VALIDITY)) {
 		err = ext4_setup_system_zone(sb);
 		if (err) {
 			ext4_msg(sb, KERN_ERR, "failed to initialize system "
 				 "zone (%d)", err);
 			goto failed_mount4a;
 		}
 	}
 	ext4_fc_replay_cleanup(sb);

 	ext4_ext_init(sb);

 	/*
 	 * Enable optimize_scan if number of groups is > threshold. This can be
 	 * turned off by passing "mb_optimize_scan=0". This can also be
 	 * turned on forcefully by passing "mb_optimize_scan=1".
 	 */
 	if (!(ctx->spec & EXT4_SPEC_mb_optimize_scan)) {
 		if (sbi->s_groups_count >= MB_DEFAULT_LINEAR_SCAN_THRESHOLD)
 			set_opt2(sb, MB_OPTIMIZE_SCAN);
 		else
 			clear_opt2(sb, MB_OPTIMIZE_SCAN);
 	}

 	err = ext4_percpu_param_init(sbi);
 	if (err)
 		goto failed_mount5;

 	err = ext4_mb_init(sb);
 	if (err) {
 		ext4_msg(sb, KERN_ERR, "failed to initialize mballoc (%d)",
 			 err);
 		goto failed_mount5;
 	}

 	/*
 	 * We can only set up the journal commit callback once
 	 * mballoc is initialized
 	 */
 	if (sbi->s_journal)
 		sbi->s_journal->j_commit_callback =
 			ext4_journal_commit_callback;

 	if (ext4_has_feature_flex_bg(sb))
 		if (!ext4_fill_flex_info(sb)) {
 			ext4_msg(sb, KERN_ERR,
 			       "unable to initialize "
 			       "flex_bg meta info!");
 			err = -ENOMEM;
 			goto failed_mount6;
 		}

 	err = ext4_register_li_request(sb, first_not_zeroed);
 	if (err)
 		goto failed_mount6;

 	err = ext4_init_orphan_info(sb);
 	if (err)
 		goto failed_mount7;
 #ifdef CONFIG_QUOTA
 	/* Enable quota usage during mount. */
 	if (ext4_has_feature_quota(sb) && !sb_rdonly(sb)) {
 		err = ext4_enable_quotas(sb);
 		if (err)
 			goto failed_mount8;
 	}
 #endif  /* CONFIG_QUOTA */

 	/*
 	 * Save the original bdev mapping's wb_err value which could be
 	 * used to detect the metadata async write error.
 	 */
 	errseq_check_and_advance(&sb->s_bdev->bd_mapping->wb_err,
 				 &sbi->s_bdev_wb_err);
 	EXT4_SB(sb)->s_mount_state |= EXT4_ORPHAN_FS;
 	ext4_orphan_cleanup(sb, es);
 	EXT4_SB(sb)->s_mount_state &= ~EXT4_ORPHAN_FS;
 	/*
 	 * Update the checksum after updating free space/inode counters and
 	 * ext4_orphan_cleanup. Otherwise the superblock can have an incorrect
 	 * checksum in the buffer cache until it is written out and
 	 * e2fsprogs programs trying to open a file system immediately
 	 * after it is mounted can fail.
 	 */
 	ext4_superblock_csum_set(sb);
 	if (needs_recovery) {
 		ext4_msg(sb, KERN_INFO, "recovery complete");
 		err = ext4_mark_recovery_complete(sb, es);
 		if (err)
 			goto failed_mount9;
 	}

 	if (test_opt(sb, DISCARD) && !bdev_max_discard_sectors(sb->s_bdev)) {
 		ext4_msg(sb, KERN_WARNING,
 			 "mounting with \"discard\" option, but the device does not support discard");
 		clear_opt(sb, DISCARD);
 	}

 	if (es->s_error_count) {
 		sbi->s_err_report_sec = 5*60;	/* first time  5 minutes */
 		mod_timer(&sbi->s_err_report,
 				  jiffies + secs_to_jiffies(sbi->s_err_report_sec));
 	}
 	sbi->s_err_report_sec = 24*60*60; /* Once a day */

 	/* Enable message ratelimiting. Default is 10 messages per 5 secs. */
 	ratelimit_state_init(&sbi->s_err_ratelimit_state, 5 * HZ, 10);
 	ratelimit_state_init(&sbi->s_warning_ratelimit_state, 5 * HZ, 10);
 	ratelimit_state_init(&sbi->s_msg_ratelimit_state, 5 * HZ, 10);
 	atomic_set(&sbi->s_warning_count, 0);
 	atomic_set(&sbi->s_msg_count, 0);

 	/* Register sysfs after all initializations are complete. */
 	err = ext4_register_sysfs(sb);
 	if (err)
 		goto failed_mount9;

 	return 0;

 failed_mount9:
 	ext4_quotas_off(sb, EXT4_MAXQUOTAS);
 failed_mount8: __maybe_unused
 	ext4_release_orphan_info(sb);
 failed_mount7:
 	ext4_unregister_li_request(sb);
 failed_mount6:
 	ext4_mb_release(sb);
 	ext4_flex_groups_free(sbi);
 failed_mount5:
 	ext4_percpu_param_destroy(sbi);
 	ext4_ext_release(sb);
 	ext4_release_system_zone(sb);
 failed_mount4a:
 	dput(sb->s_root);
 	sb->s_root = NULL;
 failed_mount4:
 	ext4_msg(sb, KERN_ERR, "mount failed");
 	if (EXT4_SB(sb)->rsv_conversion_wq)
 		destroy_workqueue(EXT4_SB(sb)->rsv_conversion_wq);
 failed_mount_wq:
 	ext4_xattr_destroy_cache(sbi->s_ea_inode_cache);
 	sbi->s_ea_inode_cache = NULL;

 	ext4_xattr_destroy_cache(sbi->s_ea_block_cache);
 	sbi->s_ea_block_cache = NULL;

 	if (sbi->s_journal) {
 		ext4_journal_destroy(sbi, sbi->s_journal);
 	}
 failed_mount3a:
 	ext4_es_unregister_shrinker(sbi);
 failed_mount3:
 	/* flush s_sb_upd_work before sbi destroy */
 	flush_work(&sbi->s_sb_upd_work);
 	ext4_stop_mmpd(sbi);
 	timer_delete_sync(&sbi->s_err_report);
 	ext4_group_desc_free(sbi);
 failed_mount:
 #if IS_ENABLED(CONFIG_UNICODE)
 	utf8_unload(sb->s_encoding);
 #endif

 #ifdef CONFIG_QUOTA
 	for (unsigned int i = 0; i < EXT4_MAXQUOTAS; i++)
 		kfree(get_qf_name(sb, sbi, i));
 #endif
 	fscrypt_free_dummy_policy(&sbi->s_dummy_enc_policy);
 	brelse(sbi->s_sbh);
 	if (sbi->s_journal_bdev_file) {
 		invalidate_bdev(file_bdev(sbi->s_journal_bdev_file));
 		bdev_fput(sbi->s_journal_bdev_file);
 	}
 out_fail:
 	invalidate_bdev(sb->s_bdev);
 	sb->s_fs_info = NULL;
 	return err;
 }



